                var key = entry.diagnostic ? ('diag-' + index) : entry.childId;
                var name = entry.diagnostic
                    ? ('诊断行（' + String(entry.reason || 'corrupt') + '）')
                    : (entry.label || entry.childId.slice(0, 12));
